---OpenStore 
---@param openId number
---@param excludeIds table
---@param exParameter table
---@param isStack boolean 是否是导航条的跳转
function StoreUtils.OpenStore(openId, excludeIds, exParameter, isStack)
    isStack = (not checkBool(isStack)) ---初始为true入栈的操作
    openId = checkNumber(openId)
    local parameters = {}
    
    -- 判断当前商城是否开启
    local dialogs = UIModule.CurrentScreen.dialogs
    for i, v in pairs(dialogs) do
        if v.Argument.id == Constants.UITypeIds.StoreEntry then
            if exParameter.hideToggle then
                exParameter.hideToggle = false
            end
            Events.Broadcast(Constants.EventNames.StoreEntrySwitch, {openId = openId, exParameter = exParameter})
            return
        end
    end
    
    parameters.exParameter = exParameter
    parameters.OpenId = openId
    KCookie.Set(Constants.UICacheDataKeys.STORE_ENTRY_SELECTED_OPEN_ID, nil)
    return UIModule.OpenDialog({ id = Constants.UITypeIds.StoreEntry, parameters = parameters }, excludeIds, isStack)
end

