function StoreUtils.ResizeContent(content, destCnt, childObj)
    local srcCnt = content.childCount
    local minusCnt = destCnt - srcCnt
    --printInfo(minusCnt)
    if minusCnt < 0 then
        minusCnt = math.abs(minusCnt)
        for i = srcCnt, srcCnt - minusCnt, -1 do
            local idx = i - 1
            KTool.SetActive(content:GetChild(idx).gameObject, false)
        end
    elseif minusCnt > 0 then
        for i = 1, minusCnt do
            GameObject.Instantiate(childObj, content)
        end
    end
    for i = 1, destCnt do
        local idx = i - 1
        KTool.SetActive(content:GetChild(idx).gameObject, true)
    end
end

