local SecondPerMin = 60
local SecondPerHour = 3600  -- 60*60
local SecondPerDay = 86400 -- 24*60*60
local NumberTheme = "<color=#000000><size=22>%d</size></color>"
local NumberNoSizeColor = "%d"
function StoreUtils.FormatTime(second, theme)
    if second < SecondPerMin then
        return localize("小于一分钟")
    else
        if theme == nil or not theme then
            theme = NumberTheme
        else
            theme = NumberNoSizeColor
        end
        local result = {}
        if second > SecondPerDay then
            table.insert(result, string.format(theme, math.floor(second / SecondPerDay)))
            table.insert(result, localize("天"))
            second = second % SecondPerDay
        end

        if second > SecondPerHour then
            table.insert(result, string.format(theme, math.floor(second / SecondPerHour)))
            table.insert(result, localize("时"))
            second = second % SecondPerHour
        end

        if second > SecondPerMin then
            table.insert(result, string.format(theme, math.floor(second / SecondPerMin)))
            table.insert(result, localize("分"))
        end

        return table.concat(result)
    end

end

function StoreUtils.ConventLeftTimeText(seconds)
    if seconds <= 0 then
        return localize("活动已结束")
    end
    if seconds >= 86400 then
        -- 返回天数
        return localize("_num_天", {_num_ = math.floor(seconds / 86400)})
    elseif seconds >= 3600 then
        -- 返回小时
        return localize("_num_小时", {_num_ = math.floor(seconds / 3600)})
    elseif seconds >= 60 then
        -- 返回分钟
        return localize("_num_分钟", {_num_ = math.floor(seconds / 60)})
    else
        -- 返回秒数
        return localize("_num_秒", {_num_ = math.floor(seconds)})
    end
end

function StoreUtils.StoreCanRefresh(store)
    if isSet(store, "refreshLeftFreeTimes") then
        if store.refreshLeftFreeTimes > 0 then
            return StoreConstants.RefreshState.CanRefresh
        end
    end

    if isSet(store, "refreshLeftTimes") then
        if store.refreshLeftTimes == 0 then
            return StoreConstants.RefreshState.WithoutCounts
        --elseif store.refreshLeftTimes == -1 then
        --    return StoreConstants.RefreshState.CanRefresh
        end
    else
        return StoreConstants.RefreshState.OnlyAutoRefresh
    end

    if isSet(store, "refreshConsume") then
        local have = GoodsUtils.GetThingNo(store.refreshConsume.goodsId)
        if have >= store.refreshConsume.num then
            return StoreConstants.RefreshState.CanRefresh
        else
            return StoreConstants.RefreshState.LeakGoods
        end
    end

    return StoreConstants.RefreshState.Unknown
end

function StoreUtils.StoreRefreshError(refreshState)
    if refreshState == StoreConstants.RefreshState.WithoutCounts then
        return localize("刷新次数不足")
    elseif refreshState == StoreConstants.RefreshState.LeakGoods then
        return localize("消耗道具不足")
    elseif refreshState == StoreConstants.RefreshState.OnlyAutoRefresh then
        return localize("只能自动刷新")
    elseif refreshState == StoreConstants.RefreshState.Unknown then
        return localize("未知错误")
    end
end

function StoreUtils.ProductIsSoldOut(product)
    if not isSet(product, "currentStock") then
        return false
    end
    if product.stock ~= -1 then
        return product.currentStock == 0
    else
        return false
    end
end

function StoreUtils.ProductIsLocked(product)
    if not isSet(product, "unlock") then
        return false
    end

    --p.targetType
    --p.targetId =
    --p.targetNum 
    local isLocked = false
    local lockedDescr = ''
    for i = 1, #product.unlock do
        isLocked = isLocked or not GameUtils.IsUnlockedSingle(product.unlock[i].targetType, product.unlock[i].targetNum, product.unlock[i].targetId)
        if isLocked then
            lockedDescr = GameUtils.GetUnlockDescription(tostring(product.unlock[i].targetType), tostring(product.unlock[i].targetNum))
            break
        end
    end
    return isLocked, lockedDescr
end

