function StoreUtils.GetAllExchangeFrags()
    local cardComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardData = CardUtils.SortCardBySortType(cardComp.cards, Constants.SortType.Quality, true)
    --print(table.dump(consume))
    local tabData = {}
    local cardConfMgr = CardConfMgr:GetInstance()
    for i = 1, #cardData do
        if checkInt(cardData[i].finalSkillLevel) == cardConfMgr:GetMaxFinalSkillLv() then
            local consume = cardConfMgr:GetSkillSPLevelUpByReFID(cardData[i].cardId, 4)[1]
            consume.goodsNum = GoodsUtils.GetThingNo(consume.goodsId)
            if consume.goodsNum > 0 then
                table.insert(tabData, consume)
            end
        end
    end
    return tabData
end

