function StoreUtils.RequestProxy(requestPath, openId, productId, buyNum, price, currency, callback, activityId)
    local proxyOpenId = openId
    local proxyProductId = productId
    local proxyBuyNum = buyNum
    local proxyCurrency = currency
    local proxyCallback = callback
    local proxyPrice = price
    local proxyActivityId = activityId
    --printInfo(requestPath)\
    local data = { productId = proxyProductId, num = proxyBuyNum }
    data.currency = proxyCurrency
    data.activityUuid = proxyActivityId
    
    GameUtils.Request(requestPath, data,
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local responseData = checkTable(response.data)
                    if #responseData.rewards > 0 then
                        local consume = {}

                        table.insert(consume, { ["num"] = -proxyPrice * proxyBuyNum;
                                                ["goodsId"] = proxyCurrency; })
                        GoodsUtils.DrawRewards(consume)
                        GoodsUtils.DrawRewards(responseData.rewards)
                        
                        CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_shop_buy)

                        if next(checkTable(responseData.nextChest)) ~= nil then
                            StoreUtils.RefreshNextChest(proxyOpenId, proxyProductId, responseData.nextChest)
                        else
                            StoreUtils.RefreshStock(proxyOpenId, proxyProductId, proxyBuyNum)
                        end
                        

                        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
                        if proxyCallback ~= nil then
                            proxyCallback()
                        end
                    end
                end
            end, function(errStr)
                if string.isEmpty(errStr) or errStr == nil then
                    return
                end
                printError("store buy" .. errStr)
            end)
end

