---@param quality Constants.QualityType 道具品质
function StoreUtils.GetGoodsBgByQuality(quality)
    local bg = "UIAtlas/common2/common_frame_goods_1_s.png"
    if (quality == Constants.QualityType.Whit) then
        bg = "UIAtlas/common2/common_frame_goods_1_s.png"
    elseif (quality == Constants.QualityType.Green) then
        bg = "UIAtlas/common2/common_frame_goods_2_s.png"
    elseif (quality == Constants.QualityType.Blue) then
        bg = "UIAtlas/common2/common_frame_goods_3_s.png"
    elseif (quality == Constants.QualityType.Purple) then
        bg = "UIAtlas/common2/common_frame_goods_4_s.png"
    elseif (quality == Constants.QualityType.Orange) then
        bg = "UIAtlas/common2/common_frame_goods_5_s.png"
    elseif (quality == Constants.QualityType.Red) then
        bg = "UIAtlas/common2/common_frame_goods_6_s.png"
    elseif (quality == Constants.QualityType.Colours) then
        bg = "UIAtlas/common2/common_frame_goods_6_s.png"
    end
    return bg
end

