---刷新累充红点(临时处理)
function StoreUtils.RefreshCumulativeRechargeRedPoint()
    GameUtils.Request(Interfaces.PlayerPayCumulative, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        local jsonData = response.data
        local listRewardIds = checkTable(jsonData.payCumulative)
        
        local listRechargeValue = {}
        local tableFile = self.settingMgr:Get(AutoIds.IdSetting1801)
        for i, row in pairs(tableFile) do
            local listData = {
                id =  parse_number(row, "id"),
                amount = parse_number(row, "amount")
            }
            table.insert(listRechargeValue, listData)
        end
        table.sort(listRechargeValue, function(a, b)
            return a.amount < b.amount
        end)
        
        local curAmount = nil
        local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        if not IsNull(playerComp) then
            local playDJ = playerComp.playerDojo
            if not IsNull(playDJ) then
                curAmount = playDJ.payCumulative
            end
        end

        local RedPointState = -1
        for i, v in ipairs(checkTable(listRechargeValue)) do
            local acquired = false
            for _, id in ipairs(listRewardIds) do
                if checkInt(v.id) == checkInt(id) then
                    acquired = true
                    break
                end
            end
            if not acquired and v.amount <= curAmount then
                RedPointState = 0
                break
            end
        end
        GameUtils.UpdateServerRedPointData({unMallAccmulativePay = RedPointState})
        Events.Broadcast(Constants.EventNames.StoreAccumulativePayRefresh)
    end)
end

---检查道具需求是否满足
---@param consume table
function StoreUtils.CheckConsume(consume)
    for i, v in ipairs(consume) do
        if GoodsUtils.GetThingNo(v.goodsId) < checkInt(v.num) then
            StoreUtils.OpenGoodsObtainDialog(v.goodsId)
            return false
        end
    end
    return true
end

---开启道具获取页面
---@param goodsId integer 道具id
function StoreUtils.OpenGoodsObtainDialog(goodsId, node)
    if goodsId == Constants.Currency.FreeDiamondId then
        StoreUtils.OpenDiamondExchangeDialog()
        UIModule.CloseDialog(node)
    elseif goodsId == Constants.Currency.PayDiamondId then
        StoreUtils.OpenRechargePopUp()
        UIModule.CloseDialog(node)
    else
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        GameUtils.Toast(localize("_name_不足", {_name_ = vo.name}))
    end
end

---检测玩家等级是否满足
---@param  targetLevel integer 目标等级
---@return boolean 是否满足
function StoreUtils.CheckPlayerLevelSatisfy(targetLevel)
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local level = checkInt(playerComponent.playerDojo.level)
    return level >= checkInt(targetLevel)
end

